import { GoogleGenAI, Type } from "@google/genai";
import { DailyActivity } from "../types";

const apiKey = process.env.API_KEY || ''; 
// In a real scenario, we handle missing keys gracefully, but instructions say assume it's there.
const ai = new GoogleGenAI({ apiKey });

const CHAT_SYSTEM_INSTRUCTION = `
Ты — эмпатичный, теплый и профессиональный помощник для родителей (вроде опытного педиатра или детского психолога). 
Твоя цель — поддержать родителя, снизить тревожность и дать мягкий, обоснованный совет.
1. Тон общения: дружелюбный, спокойный, "на ты", без канцеляризмов.
2. Структура ответа: сначала валидация эмоций родителя ("Понимаю, это непросто..."), затем объяснение поведения ребенка с точки зрения развития мозга/физиологии, и в конце — простой практический совет.
3. Не ставь диагнозы. Если вопрос медицинский и опасный, мягко направь к врачу.
4. Отвечай кратко, но ёмко (до 100 слов), если не попросили подробнее.
`;

export const chatWithPediatrician = async (message: string, history: { role: 'user' | 'model'; text: string }[]) => {
  try {
    const chat = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: CHAT_SYSTEM_INSTRUCTION,
        temperature: 0.7,
      },
      history: history.map(h => ({ role: h.role, parts: [{ text: h.text }] })),
    });

    const result = await chat.sendMessage({ message });
    return result.text;
  } catch (error) {
    console.error("Gemini Chat Error:", error);
    return "Извини, сейчас я немного устал. Попробуй спросить меня чуть позже.";
  }
};

export const generateDailyActivity = async (ageMonths: number): Promise<DailyActivity> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Придумай одну конкретную, простую развивающую игру для ребенка возраста ${ageMonths} месяцев.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING, description: "Короткое название игры" },
            description: { type: Type.STRING, description: "Инструкция для родителя, теплая и понятная" },
            category: { type: Type.STRING, enum: ['Motor', 'Sensory', 'Cognitive', 'Social'] },
            duration: { type: Type.STRING, description: "Пример: '5-10 мин'" },
          },
          required: ['title', 'description', 'category', 'duration'],
        },
      },
    });

    const text = response.text;
    if (!text) throw new Error("No text returned");

    const data = JSON.parse(text);
    return { ...data, isCompleted: false };
  } catch (error) {
    console.error("Gemini Activity Error:", error);
    // Fallback if AI fails
    return {
      title: "Игра в прятки с платочком",
      description: "Накройте любимую игрушку платком и спросите 'Где мишка?'. Это развивает понимание постоянства объектов.",
      category: "Cognitive",
      duration: "5 мин",
      isCompleted: false
    };
  }
};

