export const GrowthDiary: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'text' | 'audio'>('text');
  const [isRecording, setIsRecording] = useState(false);
  const [entries, setEntries] = useState<DiaryEntry[]>([
    {
        id: '1',
        date: '12 Окт 2023',
        type: 'capsule',
        content: 'Первая улыбка во сне. Я плакала от счастья.',
        tags: ['6 месяцев']
    },
    {
        id: '2',
        date: '15 Окт 2023',
        type: 'quote',
        content: 'Любимая еда: Тыква (на удивление).',
        tags: []
    },
    {
        id: '3',
        date: '20 Окт 2023',
        type: 'audio',
        content: 'Первый смех',
        duration: '0:15',
        tags: ['эмоции']
    }
  ]);

  const [recordingTime, setRecordingTime] = useState(0);
  const [mediaRecorder, setMediaRecorder] = useState<MediaRecorder | null>(null);

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const recorder = new MediaRecorder(stream);
      const chunks: BlobPart[] = [];

      recorder.ondataavailable = (e) => chunks.push(e.data);
      recorder.onstop = () => {
        const blob = new Blob(chunks, { type: 'audio/webm' });
        const url = URL.createObjectURL(blob);
        const newEntry: DiaryEntry = {
            id: Date.now().toString(),
            date: new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'short', year: 'numeric' }),
            type: 'audio',
            content: 'Новая аудио-заметка',
            duration: `0:${recordingTime < 10 ? '0' + recordingTime : recordingTime}`,
            audioUrl: url
        };
        setEntries(prev => [newEntry, ...prev]);
        setRecordingTime(0);
      };

      recorder.start();
      setMediaRecorder(recorder);
      setIsRecording(true);

      // Simulate timer
      const timer = setInterval(() => {
        setRecordingTime(prev => prev + 1);
      }, 1000);

      // Store timer ID on recorder instance for cleanup (hacky but works for demo)
      (recorder as any).timerId = timer;

    } catch (err) {
      console.error("Mic access denied", err);
      alert("Нужен доступ к микрофону");
    }
  };

  const stopRecording = () => {
    if (mediaRecorder && isRecording) {
      mediaRecorder.stop();
      clearInterval((mediaRecorder as any).timerId);
      setIsRecording(false);
      mediaRecorder.stream.getTracks().forEach(track => track.stop());
    }
  };

  return (
    <div className="px-6 pt-8 pb-20">
      <div className="flex items-center justify-between mb-6">
         <div>
            <h2 className="text-2xl font-bold text-warm-900">Дневник</h2>
            <p className="text-xs text-warm-500">Моменты, которые нельзя забыть</p>
         </div>
         <button className="bg-warm-900 text-white p-3 rounded-full shadow-lg shadow-warm-900/20 active:scale-95 transition-transform">
            <Plus size={24} />
         </button>
      </div>

      {/* Tabs */}
      <div className="flex p-1 bg-warm-100 rounded-xl mb-8">
        <button 
            onClick={() => setActiveTab('text')}
            className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${activeTab === 'text' ? 'bg-white text-warm-900 shadow-sm' : 'text-warm-500'}`}
        >
            Заметки
        </button>
        <button 
            onClick={() => setActiveTab('audio')}
            className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all flex items-center justify-center gap-2 ${activeTab === 'audio' ? 'bg-white text-primary-600 shadow-sm' : 'text-warm-500'}`}
        >
            <Mic size={14} />
            Аудио-капсулы
        </button>
      </div>

      {activeTab === 'audio' && (
         <div className="mb-8">
            <div className={`rounded-2xl p-6 flex flex-col items-center justify-center transition-all ${isRecording ? 'bg-red-50 border border-red-100' : 'bg-primary-50 border border-primary-100 border-dashed'}`}>
                {isRecording ? (
                    <>
                        <div className="w-16 h-16 rounded-full bg-red-500 flex items-center justify-center animate-pulse mb-4 shadow-lg shadow-red-200">
                             <Mic size={32} className="text-white" />
                        </div>
                        <h3 className="font-bold text-red-900 mb-1">Запись... 0:{recordingTime < 10 ? '0' + recordingTime : recordingTime}</h3>
                        <p className="text-xs text-red-400 mb-4">Ловим первые звуки</p>
                        <button onClick={stopRecording} className="px-6 py-2 bg-white text-red-500 font-bold rounded-full shadow-sm text-sm">
                            Стоп
                        </button>
                    </>
                ) : (
                    <>
                        <button onClick={startRecording} className="w-16 h-16 rounded-full bg-primary-500 flex items-center justify-center mb-4 shadow-lg shadow-primary-200 hover:scale-105 transition-transform">
