      <div className="space-y-8 relative">
        {/* Timeline Line */}
        <div className="absolute left-4 top-4 bottom-0 w-0.5 bg-warm-200" />

        {entries.filter(e => activeTab === 'audio' ? e.type === 'audio' : e.type !== 'audio').map((entry) => (
