import { GoogleGenAI, Type } from "@google/genai";
import { DailyActivity } from "../types";

const apiKey = process.env.API_KEY || ''; 
const ai = new GoogleGenAI({ apiKey });

const getSystemInstruction = (parentName: string, childName: string, ageMonths: number) => `
Ты — эмпатичный, теплый и профессиональный помощник для родителя по имени ${parentName} (вроде опытного педиатра или детского психолога). 
Ребенка зовут ${childName}, ему сейчас ${ageMonths} месяцев.
Твоя цель — поддержать родителя, снизить тревожность и дать мягкий, обоснованный совет, учитывая возраст ребенка.

1. Тон общения: дружелюбный, спокойный, "на ты", без канцеляризмов.
2. Структура ответа: сначала валидация эмоций родителя ("Понимаю, это непросто..."), затем объяснение поведения ребенка с точки зрения развития мозга/физиологии, и в конце — простой практический совет.
3. Не ставь диагнозы. Если вопрос медицинский и опасный, мягко направь к врачу.
4. Отвечай кратко, но ёмко (до 100 слов), если не попросили подробнее.
`;

export const chatWithPediatrician = async (
  message: string, 
  history: { role: 'user' | 'model'; text: string }[],
  context: { parentName: string; childName: string; ageMonths: number }
) => {
  try {
    const chat = ai.chats.create({
      model: 'gemini-3-flash-preview',
      config: {
        systemInstruction: getSystemInstruction(context.parentName, context.childName, context.ageMonths),
        temperature: 0.7,
      },
      history: history.map(h => ({ role: h.role, parts: [{ text: h.text }] })),
    });

    const result = await chat.sendMessage({ message });
    return result.text;
  } catch (error) {
    console.error("Gemini Chat Error:", error);
    return "Извини, сейчас я немного устал. Попробуй спросить меня чуть позже.";
  }
};

export const generateDailyActivity = async (ageMonths: number, childName: string): Promise<DailyActivity> => {
  try {
    // Determine development focus based on age
    let focus = "общее развитие";
    if (ageMonths < 3) focus = "зрительный контакт и укрепление шеи";
    else if (ageMonths < 6) focus = "перевороты и хват";
    else if (ageMonths < 9) focus = "ползание и лепет";
    else if (ageMonths < 12) focus = "первые шаги и мелкая моторика";

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Придумай одну конкретную, простую развивающую игру для ребенка по имени ${childName} возраста ${ageMonths} месяцев (акцент на ${focus}).`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING, description: "Короткое название игры" },
            description: { type: Type.STRING, description: `Инструкция для родителя. Используй имя ${childName}.` },
            category: { type: Type.STRING, enum: ['Motor', 'Sensory', 'Cognitive', 'Social'] },
            duration: { type: Type.STRING, description: "Пример: '5-10 мин'" },
          },
          required: ['title', 'description', 'category', 'duration'],
        },
      },
    });

    const text = response.text;
    if (!text) throw new Error("No text returned");

    const data = JSON.parse(text);
    return { ...data, isCompleted: false };
  } catch (error) {
    console.error("Gemini Activity Error:", error);
    // Fallback if AI fails
    return {
      title: "Игра в прятки с платочком",
      description: `Накройте любимую игрушку платком и спросите 'Где мишка?'. Это развивает понимание постоянства объектов.`,
      category: "Cognitive",
      duration: "5 мин",
      isCompleted: false
    };
  }
};

export const generateBedtimeStory = async (dayContext: string, childName: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Напиши очень короткую (2-3 минуты чтения), убаюкивающую терапевтическую сказку для малыша на ночь. 
      Главный герой - малыш по имени ${childName}.
      Контекст дня: ${dayContext}. 
      Используй мягкие, "сонные" слова, уменьшительно-ласкательные суффиксы.`,
    });
    return response.text || `Жила-была звездочка, которая смотрела на спящего ${childName}...`;
  } catch (error) {
    return "Сегодня сказки отдыхают, но завтра обязательно будут новые...";
  }
};

import React, { useState } from 'react';
import { UserState } from '../types';
import { ArrowRight, Baby, User, Calendar, Heart } from 'lucide-react';

interface OnboardingProps {
  onComplete: (data: UserState) => void;
}

export const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState<Partial<UserState>>({
    parentName: '',
    childName: '',
    childBirthDate: '',
  });

  const handleNext = () => {
    if (step < 3) {
      setStep(step + 1);
    } else {
      if (formData.parentName && formData.childName && formData.childBirthDate) {
        onComplete({
          parentName: formData.parentName,
          childName: formData.childName,
          childBirthDate: formData.childBirthDate,
          isOnboarded: true,
        });
      }
    }
  };

  const isStepValid = () => {
    if (step === 1) return !!formData.parentName?.trim();
    if (step === 2) return !!formData.childName?.trim();
    if (step === 3) return !!formData.childBirthDate;
    return false;
  };

  return (
    <div className="min-h-screen bg-warm-50 flex items-center justify-center p-6 font-sans">
      <div className="w-full max-w-md bg-white rounded-3xl shadow-xl p-8 relative overflow-hidden">
        {/* Progress Bar */}
        <div className="absolute top-0 left-0 w-full h-2 bg-warm-100">
            <div 
                className="h-full bg-primary-500 transition-all duration-500" 
                style={{ width: `${(step / 3) * 100}%` }}
            />
        </div>

        <div className="mt-6 mb-8 text-center">
            <div className="w-16 h-16 bg-primary-100 rounded-full flex items-center justify-center mx-auto mb-4 text-primary-600">
                {step === 1 && <User size={32} />}
                {step === 2 && <Baby size={32} />}
                {step === 3 && <Calendar size={32} />}
            </div>
            <h2 className="text-2xl font-bold text-warm-900 mb-2">
                {step === 1 && "Давайте знакомиться"}
                {step === 2 && "Кто ваш малыш?"}
                {step === 3 && "Когда важная дата?"}
            </h2>
            <p className="text-warm-500 text-sm">
                {step === 1 && "Как мне к вам обращаться?"}
                {step === 2 && "Как зовут маленького человека?"}
                {step === 3 && "Это поможет подбирать игры по возрасту."}
            </p>
        </div>

        <div className="space-y-6">
            {step === 1 && (
                <input
                    type="text"
                    value={formData.parentName}
                    onChange={(e) => setFormData({...formData, parentName: e.target.value})}
                    placeholder="Ваше имя"
                    className="w-full text-center text-xl border-b-2 border-warm-200 py-2 focus:outline-none focus:border-primary-500 bg-transparent placeholder-warm-300 text-warm-800 transition-colors"
                    autoFocus
                />
            )}

            {step === 2 && (
                <input
                    type="text"
                    value={formData.childName}
                    onChange={(e) => setFormData({...formData, childName: e.target.value})}
                    placeholder="Имя ребенка"
                    className="w-full text-center text-xl border-b-2 border-warm-200 py-2 focus:outline-none focus:border-primary-500 bg-transparent placeholder-warm-300 text-warm-800 transition-colors"
                    autoFocus
                />
            )}

            {step === 3 && (
                <input
                    type="date"
                    value={formData.childBirthDate}
                    onChange={(e) => setFormData({...formData, childBirthDate: e.target.value})}
                    className="w-full text-center text-xl border-b-2 border-warm-200 py-2 focus:outline-none focus:border-primary-500 bg-transparent text-warm-800 transition-colors"
                    max={new Date().toISOString().split('T')[0]}
                />
            )}

            <button
                onClick={handleNext}
                disabled={!isStepValid()}
                className="w-full py-4 bg-warm-900 text-white rounded-xl font-bold shadow-lg shadow-warm-900/20 disabled:opacity-50 disabled:scale-95 active:scale-95 transition-all flex items-center justify-center gap-2 group"
            >
                {step === 3 ? (
                    <>
                        Начать путешествие <Heart size={20} className="text-red-400 fill-red-400" />
                    </>
                ) : (
                    <>
                        Далее <ArrowRight size={20} className="group-hover:translate-x-1 transition-transform" />
                    </>
                )}
            </button>
        </div>
      </div>
    </div>
  );
};

