export const editChildPhoto = async (base64Image: string, stylePrompt: string): Promise<string | null> => {
  try {
    // Clean header if present
    const cleanBase64 = base64Image.replace(/^data:image\/(png|jpeg|jpg|webp);base64,/, '');

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              data: cleanBase64,
              mimeType: 'image/jpeg', // Standardizing on jpeg for API simplicity
            },
          },
          {
            text: `Transform this photo of a child. Style: ${stylePrompt}. High quality, artistic, cute. Maintain the child's general pose but change the environment and artistic style completely.`
          },
        ],
      },
      // No responseMimeType for image editing usually, we look for parts
    });

    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/png;base64,${part.inlineData.data}`;
        }
      }
    }
    return null;
  } catch (error) {
    console.error("Gemini Image Edit Error:", error);
    throw error;
  }
};

