export const MagicPhoto: React.FC = () => {
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [resultImage, setResultImage] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [selectedStyle, setSelectedStyle] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
        setResultImage(null);
        setSelectedStyle(null);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleGenerate = async () => {
    if (!selectedImage || !selectedStyle) return;

    setIsProcessing(true);
    setResultImage(null);

    try {
      const prompt = STYLES.find(s => s.id === selectedStyle)?.prompt || '';
      const result = await editChildPhoto(selectedImage, prompt);
      setResultImage(result);
    } catch (error) {
      console.error(error);
      alert("Не удалось создать магию. Попробуйте другое фото или стиль.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleReset = () => {
    setSelectedImage(null);
    setResultImage(null);
    setSelectedStyle(null);
    if (fileInputRef.current) {
        fileInputRef.current.value = '';
    }
  };

  return (
    <div className="min-h-full bg-slate-50 text-slate-900 p-6 pb-20">
      <div className="flex items-center gap-3 mb-6">
        <div className="bg-gradient-to-tr from-violet-500 to-fuchsia-500 p-2 rounded-full text-white shadow-lg">
            <Wand2 size={24} />
        </div>
        <div>
            <h2 className="text-2xl font-bold text-slate-900">AI Магия</h2>
            <p className="text-xs text-slate-500">Превратите фото в шедевр</p>
        </div>
      </div>

      {!selectedImage ? (
        <div className="flex flex-col items-center justify-center h-[60vh] border-2 border-dashed border-slate-300 rounded-3xl bg-white p-8 text-center space-y-4">
            <div className="bg-slate-100 p-6 rounded-full">
                <Camera size={48} className="text-slate-400" />
            </div>
            <div>
                <h3 className="text-lg font-bold text-slate-700">Загрузите фото</h3>
                <p className="text-sm text-slate-400 mt-1 max-w-[200px] mx-auto">
                    Выберите четкое фото малыша, чтобы магия сработала лучше всего
                </p>
            </div>
            <button 
                onClick={() => fileInputRef.current?.click()}
                className="px-8 py-3 bg-slate-900 text-white rounded-xl font-bold shadow-lg hover:scale-105 transition-transform flex items-center gap-2"
            >
                <Upload size={18} />
                Выбрать из галереи
            </button>
            <input 
                ref={fileInputRef}
                type="file" 
                accept="image/*" 
                className="hidden" 
                onChange={handleFileChange}
            />
        </div>
      ) : (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
            {/* Image Preview Area */}
            <div className="relative rounded-2xl overflow-hidden shadow-xl bg-slate-200 aspect-square">
                {isProcessing && (
                    <div className="absolute inset-0 z-20 bg-black/50 backdrop-blur-sm flex flex-col items-center justify-center text-white">
                        <Sparkles className="animate-spin mb-4 text-fuchsia-400" size={48} />
                        <p className="font-bold animate-pulse">Творим волшебство...</p>
                    </div>
                )}

                {resultImage ? (
                    <img src={resultImage} alt="Result" className="w-full h-full object-cover" />
                ) : (
                    <img src={selectedImage} alt="Original" className="w-full h-full object-cover" />
                )}

                {!isProcessing && (
                    <button 
                        onClick={handleReset}
                        className="absolute top-4 right-4 bg-white/80 p-2 rounded-full text-slate-700 shadow-sm hover:bg-white transition-colors z-30"
                    >
                        <X size={20} />
                    </button>
                )}
            </div>

            {/* Controls */}
            {!resultImage && (
                <div className="space-y-4">
                    <h3 className="font-bold text-slate-800">Выберите стиль</h3>
                    <div className="grid grid-cols-2 gap-3">
                        {STYLES.map((style) => (
                            <button
                                key={style.id}
                                onClick={() => setSelectedStyle(style.id)}
                                className={`p-3 rounded-xl border text-left transition-all ${
                                    selectedStyle === style.id 
                                    ? 'border-violet-500 bg-violet-50 shadow-md ring-1 ring-violet-500' 
                                    : 'border-slate-200 bg-white hover:border-violet-200'
                                }`}
                            >
                                <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${style.color}`}>
                                    {style.label}
                                </span>
                            </button>
                        ))}
                    </div>

                    <button
                        onClick={handleGenerate}
                        disabled={!selectedStyle || isProcessing}
                        className="w-full py-4 bg-gradient-to-r from-violet-600 to-fuchsia-600 text-white rounded-xl font-bold shadow-lg shadow-violet-200 disabled:opacity-50 disabled:scale-95 active:scale-95 transition-all flex items-center justify-center gap-2"
                    >
                        <Sparkles size={20} />
                        Сотворить магию
                    </button>
                </div>
            )}

            {/* Result Actions */}
            {resultImage && (
                <div className="flex gap-3">
                    <a 
                        href={resultImage} 
                        download="magic-baby.png"
                        className="flex-1 py-3 bg-slate-900 text-white rounded-xl font-bold flex items-center justify-center gap-2 shadow-lg"
