                        className="px-4 py-3 bg-white border border-slate-200 text-slate-700 rounded-xl font-bold flex items-center justify-center gap-2 shadow-sm"
                    >
                        <RefreshCw size={18} />
                    </button>
                </div>
            )}
        </div>
      )}
    </div>
  );
};

