  LayoutGrid, 
  Camera, 
  Wand2, 
  Moon, 
  CloudLightning, 
  Trophy 
} from 'lucide-react';
import { UserState } from '../types';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: string;
  onTabChange: (tab: string) => void;
  userState: UserState;
}

const ALL_NAV_ITEMS: Record<string, { icon: any, label: string }> = {
  'home': { icon: Home, label: 'Главная' },
  'food': { icon: Utensils, label: 'Еда' },
  'diary': { icon: BookHeart, label: 'Дневник' },
  'chat': { icon: MessageCircleHeart, label: 'Помощник' },
  'photo-ideas': { icon: Camera, label: 'Студия' },
  'magic-photo': { icon: Wand2, label: 'Магия' },
  'storyteller': { icon: Moon, label: 'Сказки' },
  'leaps': { icon: CloudLightning, label: 'Рост' },
  'quests': { icon: Trophy, label: 'Квесты' },
  'menu': { icon: LayoutGrid, label: 'Ещё' },
};

export const Layout: React.FC<LayoutProps> = ({ children, activeTab, onTabChange, userState }) => {
  // Fixed tabs
  const startItems = ['home'];
  const endItems = ['menu'];

  // Custom middle tabs from user state
  const middleItems = userState.customNavItems || ['food', 'diary', 'chat'];

  const navIds = [...startItems, ...middleItems, ...endItems];

  // Logic to highlight 'menu' tab if activeTab is a sub-feature not currently in middle nav
  const isMenuTabActive = activeTab === 'menu' || (!middleItems.includes(activeTab) && activeTab !== 'home');

  return (
    <div className="min-h-screen bg-warm-50 text-warm-900 font-sans pb-24 relative overflow-hidden">
      <div className="max-w-md mx-auto min-h-screen bg-white shadow-2xl overflow-hidden relative">
         {/* Top Decoration */}
         <div className="absolute top-0 left-0 w-full h-64 bg-gradient-to-b from-primary-100/50 to-transparent pointer-events-none -z-0" />

        {/* Content Area */}
        <main className="relative z-10 h-full overflow-y-auto no-scrollbar pb-24">
          {children}
        </main>

        {/* Bottom Navigation */}
        <nav className="absolute bottom-0 left-0 w-full bg-white/95 backdrop-blur-md border-t border-warm-200 py-3 px-2 flex justify-between items-center z-50">
          {navIds.map((id) => {
            const itemConfig = ALL_NAV_ITEMS[id] || ALL_NAV_ITEMS['menu'];
            const Icon = itemConfig.icon;

            let isActive = activeTab === id;
            // Special case for 'menu' if we are in a sub-view that isn't pinned
            if (id === 'menu' && isMenuTabActive) isActive = true;

            return (
              <button
                key={id}
                onClick={() => onTabChange(id)}
                className={`flex flex-col items-center gap-1 transition-all duration-300 w-1/5 ${
                  isActive ? 'text-primary-600 transform scale-105' : 'text-warm-300 hover:text-warm-500'
                }`}
              >
                <div className={`p-2 rounded-2xl transition-colors ${isActive ? 'bg-primary-50' : 'bg-transparent'}`}>
                    <Icon size={20} strokeWidth={isActive ? 2.5 : 2} />
                </div>
                <span className="text-[9px] font-bold tracking-tight text-center truncate w-full">{itemConfig.label}</span>
              </button>
            );
          })}
        </nav>
      </div>
    </div>
  );
};

