import React, { useState, useEffect } from 'react';
import { Layout } from './components/Layout';
import { DailyCard } from './components/DailyCard';
import { AIChat } from './components/AIChat';
import { Quests } from './components/Quests';
import { GrowthDiary } from './components/GrowthDiary';
import { FoodDiary } from './components/FoodDiary';
import { ToolsMenu } from './components/ToolsMenu';
import { Storyteller } from './components/Storyteller';
import { GrowthLeaps } from './components/GrowthLeaps';
import { PhotoIdeas } from './components/PhotoIdeas';
import { MagicPhoto } from './components/MagicPhoto';
import { Onboarding } from './components/Onboarding';
import { INITIAL_QUESTS, MOCK_ACTIVITY, MOCK_BRAIN_FACT, PARENT_AFFIRMATIONS } from './constants';
import { generateDailyActivity } from './services/geminiService';
import { DailyActivity, UserState } from './types';

function App() {
  const [activeTab, setActiveTab] = useState('home');
  const [activity, setActivity] = useState<DailyActivity>(MOCK_ACTIVITY);
  const [isLoadingActivity, setIsLoadingActivity] = useState(false);
  const [affirmation, setAffirmation] = useState('');

  // State for personalization
  const [userState, setUserState] = useState<UserState | null>(null);

  useEffect(() => {
    setAffirmation(PARENT_AFFIRMATIONS[Math.floor(Math.random() * PARENT_AFFIRMATIONS.length)]);

    // Load user state from local storage
    const savedUser = localStorage.getItem('mamaPapaUser');
    if (savedUser) {
        setUserState(JSON.parse(savedUser));
    }
  }, []);

  // Calculate age in months helper
  const getAgeMonths = () => {
    if (!userState) return 12;
    const birthDate = new Date(userState.childBirthDate);
    const today = new Date();
    let months = (today.getFullYear() - birthDate.getFullYear()) * 12;
    months -= birthDate.getMonth();
    months += today.getMonth();
    if (today.getDate() < birthDate.getDate()) months--;
    return Math.max(0, months);
  };

  const handleRefreshActivity = async () => {
    if (!userState) return;
    setIsLoadingActivity(true);
    const age = getAgeMonths();
    const newActivity = await generateDailyActivity(age, userState.childName);
    setActivity(newActivity);
    setIsLoadingActivity(false);
  };

  const handleCompleteActivity = () => {
    setActivity(prev => ({ ...prev, isCompleted: true }));
  };

  const handleOnboardingComplete = (data: UserState) => {
    const fullData = {
      ...data,
      customNavItems: ['food', 'diary', 'chat'] // Default nav items
    };
    setUserState(fullData);
    localStorage.setItem('mamaPapaUser', JSON.stringify(fullData));
    generateDailyActivity(0, data.childName).then(act => setActivity(act));
  };

  const handleUpdateNav = (items: string[]) => {
    if (!userState) return;
    const newState = { ...userState, customNavItems: items };
    setUserState(newState);
    localStorage.setItem('mamaPapaUser', JSON.stringify(newState));
  };

  if (!userState || !userState.isOnboarded) {
      return <Onboarding onComplete={handleOnboardingComplete} />;
  }

  // Helper to render content based on activeTab state
  const renderContent = () => {
    switch (activeTab) {
      case 'home':
        return (
          <>
            <div className="px-6 pt-6 pb-0">
                 <div className="bg-warm-100/50 rounded-lg p-3 text-center border border-warm-200/50">
                    <p className="text-xs font-semibold text-warm-600">✨ {affirmation}</p>
                 </div>
            </div>
            <DailyCard 
                activity={activity} 
                brainFact={MOCK_BRAIN_FACT}
                userState={userState}
                onComplete={handleCompleteActivity}
                onRefreshActivity={handleRefreshActivity}
                loading={isLoadingActivity}
            />
          </>
        );
      case 'food':
        return <FoodDiary />;
      case 'diary':
        return <GrowthDiary />;
      case 'chat':
        return <AIChat userState={userState} />;
      case 'menu':
        return <ToolsMenu onNavigate={setActiveTab} userState={userState} onUpdateNav={handleUpdateNav} />;
      case 'storyteller':
        return <Storyteller userState={userState} />;
      case 'leaps':
        return <GrowthLeaps />;
      case 'quests':
        return <Quests quests={INITIAL_QUESTS} />;
      case 'photo-ideas':
        return <PhotoIdeas userState={userState} />;
      case 'magic-photo':
        return <MagicPhoto />;
      default:
        return <div className="p-6">Раздел в разработке</div>;
    }
  };

  return (
    <Layout activeTab={activeTab} onTabChange={setActiveTab} userState={userState}>
      {renderContent()}
    </Layout>
  );
}

export default App;

import React, { useState } from 'react';
import { UserState } from '../types';
import { ArrowRight, Baby, User, Calendar, Heart } from 'lucide-react';

interface OnboardingProps {
  onComplete: (data: UserState) => void;
}

export const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState<Partial<UserState>>({
    parentName: '',
    childName: '',
    childBirthDate: '',
  });

  const handleNext = () => {
    if (step < 3) {
      setStep(step + 1);
    } else {
      if (formData.parentName && formData.childName && formData.childBirthDate) {
        onComplete({
          parentName: formData.parentName,
          childName: formData.childName,
          childBirthDate: formData.childBirthDate,
          isOnboarded: true,
          customNavItems: ['food', 'diary', 'chat'], // Initial default layout
        });
      }
    }
  };

  const isStepValid = () => {
    if (step === 1) return !!formData.parentName?.trim();
    if (step === 2) return !!formData.childName?.trim();
    if (step === 3) return !!formData.childBirthDate;
    return false;
  };

  return (
    <div className="min-h-screen bg-warm-50 flex items-center justify-center p-6 font-sans">
      <div className="w-full max-w-md bg-white rounded-3xl shadow-xl p-8 relative overflow-hidden">
        {/* Progress Bar */}
        <div className="absolute top-0 left-0 w-full h-2 bg-warm-100">
            <div 
                className="h-full bg-primary-500 transition-all duration-500" 
                style={{ width: `${(step / 3) * 100}%` }}
            />
        </div>

        <div className="mt-6 mb-8 text-center">
            <div className="w-16 h-16 bg-primary-100 rounded-full flex items-center justify-center mx-auto mb-4 text-primary-600">
                {step === 1 && <User size={32} />}
                {step === 2 && <Baby size={32} />}
                {step === 3 && <Calendar size={32} />}
            </div>
            <h2 className="text-2xl font-bold text-warm-900 mb-2">
                {step === 1 && "Давайте знакомиться"}
                {step === 2 && "Кто ваш малыш?"}
                {step === 3 && "Когда важная дата?"}
            </h2>
            <p className="text-warm-500 text-sm">
                {step === 1 && "Как мне к вам обращаться?"}
                {step === 2 && "Как зовут маленького человека?"}
                {step === 3 && "Это поможет подбирать игры по возрасту."}
            </p>
        </div>

        <div className="space-y-6">
            {step === 1 && (
                <input
                    type="text"
                    value={formData.parentName}
                    onChange={(e) => setFormData({...formData, parentName: e.target.value})}
                    placeholder="Ваше имя"
                    className="w-full text-center text-xl border-b-2 border-warm-200 py-2 focus:outline-none focus:border-primary-500 bg-transparent placeholder-warm-300 text-warm-800 transition-colors"
                    autoFocus
                />
            )}

            {step === 2 && (
                <input
                    type="text"
                    value={formData.childName}
                    onChange={(e) => setFormData({...formData, childName: e.target.value})}
                    placeholder="Имя ребенка"
                    className="w-full text-center text-xl border-b-2 border-warm-200 py-2 focus:outline-none focus:border-primary-500 bg-transparent placeholder-warm-300 text-warm-800 transition-colors"
                    autoFocus
                />
            )}

            {step === 3 && (
                <input
                    type="date"
                    value={formData.childBirthDate}
                    onChange={(e) => setFormData({...formData, childBirthDate: e.target.value})}
                    className="w-full text-center text-xl border-b-2 border-warm-200 py-2 focus:outline-none focus:border-primary-500 bg-transparent text-warm-800 transition-colors"
                    max={new Date().toISOString().split('T')[0]}
                />
            )}

            <button
                onClick={handleNext}
                disabled={!isStepValid()}
                className="w-full py-4 bg-warm-900 text-white rounded-xl font-bold shadow-lg shadow-warm-900/20 disabled:opacity-50 disabled:scale-95 active:scale-95 transition-all flex items-center justify-center gap-2 group"
            >
                {step === 3 ? (
                    <>
                        Начать путешествие <Heart size={20} className="text-red-400 fill-red-400" />
                    </>
                ) : (
                    <>
                        Далее <ArrowRight size={20} className="group-hover:translate-x-1 transition-transform" />
                    </>
                )}
            </button>
        </div>
      </div>
    </div>
  );
};

