                brainFact={MOCK_BRAIN_FACT}
                userState={userState}
                onComplete={handleCompleteActivity}
                onRefreshActivity={handleRefreshActivity}
                loading={isLoadingActivity}
            />
          </>
        );
      case 'food':
        return <FoodDiary />;
      case 'diary':
        return <GrowthDiary />;
      case 'chat':
        return <AIChat userState={userState} />;
      case 'menu':
        return <ToolsMenu onNavigate={setActiveTab} userState={userState} onUpdateNav={handleUpdateNav} />;
      case 'storyteller':
        return <Storyteller userState={userState} />;
      case 'leaps':
        return <GrowthLeaps />;
      case 'quests':
        return <Quests quests={INITIAL_QUESTS} />;
      case 'photo-ideas':
        return <PhotoIdeas userState={userState} />;
      case 'magic-photo':
        return <MagicPhoto />;
      default:
        return <div className="p-6">Раздел в разработке</div>;
    }
  };

  return (
    <Layout activeTab={activeTab} onTabChange={setActiveTab} userState={userState}>
      {renderContent()}
    </Layout>
  );
}

export default App;

import React from 'react';
import { 
  Home, 
  MessageCircleHeart, 
  BookHeart, 
  Utensils, 
  LayoutGrid, 
  Camera, 
  Wand2, 
  Moon, 
  CloudLightning, 
  Trophy 
} from 'lucide-react';
import { UserState } from '../types';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: string;
  onTabChange: (tab: string) => void;
  userState: UserState;
}

const ALL_NAV_ITEMS: Record<string, { icon: any, label: string }> = {
  'home': { icon: Home, label: 'Главная' },
  'food': { icon: Utensils, label: 'Еда' },
  'diary': { icon: BookHeart, label: 'Дневник' },
  'chat': { icon: MessageCircleHeart, label: 'Помощник' },
  'photo-ideas': { icon: Camera, label: 'Студия' },
  'magic-photo': { icon: Wand2, label: 'Магия' },
  'storyteller': { icon: Moon, label: 'Сказки' },
  'leaps': { icon: CloudLightning, label: 'Рост' },
  'quests': { icon: Trophy, label: 'Квесты' },
  'menu': { icon: LayoutGrid, label: 'Ещё' },
};

export const Layout: React.FC<LayoutProps> = ({ children, activeTab, onTabChange, userState }) => {
  // Fixed tabs
  const startItems = ['home'];
  const endItems = ['menu'];

  // Custom middle tabs from user state or fallback to defaults
  const middleItems = (userState && userState.customNavItems && userState.customNavItems.length > 0) 
    ? userState.customNavItems 
    : ['food', 'diary', 'chat'];

  const navIds = [...startItems, ...middleItems, ...endItems];

  // Logic to highlight 'menu' tab if activeTab is a sub-feature not currently in middle nav
  const isMenuTabActive = activeTab === 'menu' || (!middleItems.includes(activeTab) && activeTab !== 'home');

  return (
    <div className="min-h-screen bg-warm-50 text-warm-900 font-sans pb-24 relative overflow-hidden">
      <div className="max-w-md mx-auto min-h-screen bg-white shadow-2xl overflow-hidden relative">
         {/* Top Decoration */}
         <div className="absolute top-0 left-0 w-full h-64 bg-gradient-to-b from-primary-100/50 to-transparent pointer-events-none -z-0" />

        {/* Content Area */}
        <main className="relative z-10 h-full overflow-y-auto no-scrollbar pb-24">
          {children}
        </main>

        {/* Bottom Navigation */}
        <nav className="absolute bottom-0 left-0 w-full bg-white/95 backdrop-blur-md border-t border-warm-200 py-3 px-2 flex justify-between items-center z-50">
          {navIds.map((id) => {
            const itemConfig = ALL_NAV_ITEMS[id] || ALL_NAV_ITEMS['menu'];
            const Icon = itemConfig.icon;

            let isActive = activeTab === id;
            // Special case for 'menu' if we are in a sub-view that isn't pinned
            if (id === 'menu' && isMenuTabActive) isActive = true;

            return (
              <button
                key={id}
                onClick={() => onTabChange(id)}
                className={`flex flex-col items-center gap-1 transition-all duration-300 w-1/5 ${
                  isActive ? 'text-primary-600 transform scale-105' : 'text-warm-400 hover:text-warm-600'
                }`}
              >
                <div className={`p-2 rounded-2xl transition-colors ${isActive ? 'bg-primary-50' : 'bg-transparent'}`}>
                    <Icon size={20} strokeWidth={isActive ? 2.5 : 2} />
                </div>
                <span className={`text-[9px] font-bold tracking-tight text-center truncate w-full ${isActive ? 'text-primary-700' : 'text-warm-400'}`}>
                    {itemConfig.label}
                </span>
              </button>
            );
          })}
        </nav>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Trophy, Moon, CloudLightning, ChevronRight, Puzzle, Send, Sparkles, Camera, Wand2, Settings2, CheckCircle2, Utensils, BookHeart, MessageCircleHeart } from 'lucide-react';
import { UserState } from '../types';

interface ToolsMenuProps {
  onNavigate: (view: string) => void;
  userState: UserState;
  onUpdateNav: (items: string[]) => void;
}

export const ToolsMenu: React.FC<ToolsMenuProps> = ({ onNavigate, userState, onUpdateNav }) => {
  const [feedback, setFeedback] = useState('');
  const [isSent, setIsSent] = useState(false);
  const [isCustomizing, setIsCustomizing] = useState(false);

  const tools = [
    {
      id: 'magic-photo',
      title: 'AI Магия',
      desc: 'Превратите фото малыша в сказку',
      icon: Wand2,
      color: 'bg-violet-100 text-violet-600',
      bg: 'hover:bg-violet-50'
    },
    {
      id: 'photo-ideas',
      title: 'Фото-студия',
      desc: 'Идеи для красивых фотосессий дома',
      icon: Camera,
      color: 'bg-rose-100 text-rose-600',
      bg: 'hover:bg-rose-50'
    },
    {
      id: 'storyteller',
      title: 'AI Сказочник',
      desc: 'Создайте волшебную сказку о дне малыша',
      icon: Moon,
      color: 'bg-indigo-100 text-indigo-600',
      bg: 'hover:bg-indigo-50'
    },
    {
      id: 'leaps',
      title: 'Календарь роста',
      desc: 'Узнайте, почему малыш капризничает',
      icon: CloudLightning,
      color: 'bg-blue-100 text-blue-600',
      bg: 'hover:bg-blue-50'
    },
    {
      id: 'quests',
      title: 'Квесты развития',
      desc: 'Недельные челленджи для родителей',
      icon: Trophy,
      color: 'bg-amber-100 text-amber-600',
      bg: 'hover:bg-amber-50'
    },
  ];

  // All pinnable items with consistent icons
  const allPinnable = [
    ...tools,
    { id: 'food', title: 'Еда', desc: 'Дневник прикорма', icon: Utensils, color: 'bg-green-100 text-green-600' },
    { id: 'diary', title: 'Дневник', desc: 'История моментов', icon: BookHeart, color: 'bg-primary-100 text-primary-600' },
    { id: 'chat', title: 'Помощник', desc: 'AI консультации', icon: MessageCircleHeart, color: 'bg-blue-100 text-blue-600' },
  ];

  const togglePin = (id: string) => {
    const current = [...(userState.customNavItems || [])];
    if (current.includes(id)) {
      onUpdateNav(current.filter(i => i !== id));
    } else if (current.length < 3) {
      onUpdateNav([...current, id]);
    } else {
      // Replace the last one if we have 3
      onUpdateNav([current[1], current[2], id]);
    }
  };

  const handleSend = () => {
    if (!feedback.trim()) return;
    setIsSent(true);
    setFeedback('');
    setTimeout(() => setIsSent(false), 3000);
  };

  return (
    <div className="px-6 pt-8 pb-20">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-warm-900">Инструменты</h2>
        <button 
            onClick={() => setIsCustomizing(!isCustomizing)}
            className={`p-2 rounded-xl transition-all flex items-center gap-2 text-xs font-bold ${isCustomizing ? 'bg-primary-500 text-white shadow-lg' : 'bg-warm-100 text-warm-500'}`}
        >
            <Settings2 size={18} />
            {isCustomizing ? 'Готово' : 'Настроить меню'}
        </button>
      </div>

      {isCustomizing && (
          <div className="mb-8 p-5 bg-primary-50 rounded-2xl border border-primary-100 animate-in fade-in zoom-in duration-300 shadow-inner">
             <div className="flex items-center gap-2 mb-4">
                <Settings2 size={18} className="text-primary-600" />
                <h3 className="font-bold text-primary-900 text-sm">Ваша панель быстрого доступа</h3>
             </div>
             <p className="text-[11px] text-primary-700 mb-4 opacity-80 leading-relaxed">
                Выберите 3 инструмента, которые появятся в нижней части экрана. Нажмите на иконку, чтобы добавить или убрать раздел.
             </p>
             <div className="grid grid-cols-2 gap-2">
                {allPinnable.map(item => {
                    const isPinned = userState.customNavItems.includes(item.id);
                    const Icon = item.icon;
                    return (
                        <button 
                            key={item.id}
                            onClick={() => togglePin(item.id)}
                            className={`flex items-center gap-3 p-3 rounded-xl border transition-all text-left ${isPinned ? 'bg-white border-primary-400 shadow-md ring-1 ring-primary-100' : 'bg-white/40 border-transparent opacity-60'}`}
                        >
                            <div className={`p-1.5 rounded-lg shrink-0 ${isPinned ? 'bg-primary-100 text-primary-600' : 'bg-warm-100 text-warm-400'}`}>
                                <Icon size={16} />
                            </div>
                            <div className="flex-1 min-w-0">
                                <span className={`text-xs font-bold block truncate ${isPinned ? 'text-primary-900' : 'text-warm-800'}`}>{item.title}</span>
                                {isPinned && <span className="text-[8px] uppercase tracking-tighter text-primary-400 font-black">В меню</span>}
                            </div>
                            <CheckCircle2 size={14} className={isPinned ? 'text-primary-500' : 'text-transparent'} />
                        </button>
                    )
                })}
             </div>
          </div>
      )}

      <div className="grid gap-4 mb-8">
        {tools.map((tool) => {
            const Icon = tool.icon;
            return (
                <button 
                    key={tool.id}
                    onClick={() => onNavigate(tool.id)}
                    className={`bg-white p-4 rounded-2xl border border-warm-100 shadow-sm flex items-center gap-4 transition-all ${tool.bg} active:scale-98 text-left`}
                >
                    <div className={`p-3 rounded-full ${tool.color}`}>
                        <Icon size={24} />
                    </div>
                    <div className="flex-1">
                        <h3 className="font-bold text-warm-900">{tool.title}</h3>
                        <p className="text-xs text-warm-500">{tool.desc}</p>
                    </div>
                    <ChevronRight size={20} className="text-warm-300" />
                </button>
            )
        })}
      </div>

      {/* Feedback Section */}
      <div className="p-6 bg-gradient-to-br from-primary-100 to-warm-100 rounded-3xl relative overflow-hidden">
        <div className="absolute top-0 right-0 p-4 opacity-10 pointer-events-none">
             <Puzzle size={100} className="text-primary-800" />
        </div>

        <div className="relative z-10">
            <div className="flex items-center gap-2 mb-2">
                <Puzzle size={24} className="text-primary-600" />
                <h3 className="font-bold text-primary-900">Вместе лучше</h3>
            </div>

            <p className="text-sm text-primary-800/80 mb-4 leading-relaxed">
                Мы готовим разделы "Обмен вещами" и "Медитации". А чего не хватает вам? Напишите идею, и мы её обсудим!
            </p>

            {isSent ? (
                <div className="bg-white/60 backdrop-blur-md rounded-xl p-6 text-center animate-in fade-in zoom-in duration-300 border border-white/50">
                    <div className="flex justify-center mb-2">
                        <div className="bg-green-100 p-2 rounded-full text-green-600">
                             <Sparkles size={24} />
                        </div>
                    </div>
                    <h4 className="font-bold text-primary-900">Спасибо за идею!</h4>
                    <p className="text-xs text-primary-700 mt-1">Мы всё записали.</p>
                </div>
            ) : (
                <div className="relative group">
                    <textarea
                        value={feedback}
                        onChange={(e) => setFeedback(e.target.value)}
                        placeholder="Например: добавьте график прорезывания зубов..."
                        className="w-full bg-white/70 backdrop-blur-sm border border-white/50 rounded-xl p-4 pr-12 text-sm text-primary-900 placeholder-primary-400 focus:bg-white focus:ring-2 focus:ring-primary-400/50 focus:outline-none transition-all resize-none h-28 shadow-sm"
                    />
                    <button 
                        onClick={handleSend}
                        disabled={!feedback.trim()}
                        className="absolute bottom-3 right-3 bg-primary-600 text-white p-2 rounded-lg shadow-lg hover:bg-primary-700 hover:scale-105 active:scale-95 disabled:opacity-0 disabled:scale-75 transition-all duration-300"
                    >
                        <Send size={16} />
                    </button>
                </div>
            )}
        </div>
      </div>
    </div>
  );
};
